{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "BMS-187745 had a measured absolute oral bioavailability of 2.6% in healthy subjects, directly below the 20% threshold; its high transfer score makes this a strong anchor for low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Bambuterol, which contains the same dimethylcarbamate functionality as the query, has an oral bioavailability of about 10% in healthy adults, supporting F <20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Physostigmine, a carbamate acetylcholinesterase inhibitor, is reported to have poor oral bioavailability, consistent with low F for the query's carbamate and permanently charged pyridinium structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Agomelatine has an absolute oral bioavailability of <5% in humans, providing additional high-transfer, direct evidence for low F at the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Predicted low: the query is a permanently charged quaternary pyridinium dimethylcarbamate; high-transfer evidence from carbamate drugs (bambuterol ~10%, physostigmine poor) and other low-F compounds (<5-10%) consistently indicates F <20%, and the quaternary charge further limits membrane permeability and oral absorption.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "Fasted-state-specific pharmacokinetic data are not reported for the closest analogues; most records are general oral administration.",
    "The effect of the quaternary pyridinium charge on absorption is inferred from chemistry and related quaternary ammonium drugs rather than directly measured in the supplied evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

